-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = globalSleep, headers = {} } = {}) {
+  const maxAttempts = 3;
+  let lastError;
+
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) {
+          throw new HttpError(res.status, url);
+        }
+        // Retry 5xx errors
+        lastError = new HttpError(res.status, url);
+        if (attempt < maxAttempts - 1) {
+          await sleep(Math.pow(2, attempt) * 100);
+          continue;
+        }
+        throw lastError;
+      }
+      return res.json();
+    } catch (err) {
+      // Network errors (connection drop, timeout, etc.) are retriable
+      lastError = err;
+      if (attempt < maxAttempts - 1 && !(err instanceof HttpError && err.status >= 400 && err.status < 500)) {
+        await sleep(Math.pow(2, attempt) * 100);
+        continue;
+      }
+      throw err;
+    }
+  }
+
+  throw lastError;
