+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  let lastError;
+
+  for (let attempt = 0; attempt < 4; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const error = new HttpError(res.status, url);
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) {
+          throw error;
+        }
+        // 5xx error - save for potential retry
+        lastError = error;
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // Check if this is a 4xx HttpError (don't retry)
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+      // Other errors (network, 5xx) - save for potential retry
+      lastError = err;
+    }
+
+    // If we get here, we have an error and need to retry (or fail if last attempt)
+    if (attempt < 3) {
+      const backoffMs = 100 * Math.pow(2, attempt);
+      await sleep(backoffMs);
+    }
+  }
+
+  // All attempts exhausted
+  throw lastError;
