-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  let lastError;
+  const maxAttempts = 4; // initial + 3 retries
+
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) {
+          throw new HttpError(res.status, url);
+        }
+        lastError = new HttpError(res.status, url);
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // 4xx errors are thrown immediately, don't set lastError
+      if (err instanceof HttpError && err.status < 500) throw err;
+      lastError = err;
+    }
+
+    // Backoff before retrying (100ms, 200ms, 400ms)
+    if (attempt < maxAttempts - 1) {
+      await sleep(100 * Math.pow(2, attempt));
+    }
+  }
+
+  throw lastError;
