+  for (let attempt = 0; attempt < 3; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const err = new HttpError(res.status, url);
+        // Don't retry 4xx errors, throw immediately
+        if (res.status >= 400 && res.status < 500) throw err;
+        // For 5xx and other errors, save and retry
+        lastErr = err;
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // Don't retry 4xx errors, throw immediately
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) throw err;
+      // Save any other error and retry if we have attempts left
+      lastErr = err;
